import * as THREE from 'three';
export function contactEffects(scene){const count=128,pos=new Float32Array(count*3),color=new Float32Array(count*3),life=new Float32Array(count),velocity=new Float32Array(count*3);pos.fill(1000);const canvas=document.createElement('canvas');canvas.width=canvas.height=32;const ctx=canvas.getContext('2d'),g=ctx.createRadialGradient(16,16,0,16,16,16);g.addColorStop(0,'#fff');g.addColorStop(.22,'#ffffffee');g.addColorStop(1,'#ffffff00');ctx.fillStyle=g;ctx.fillRect(0,0,32,32);const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(pos,3));geo.setAttribute('color',new THREE.BufferAttribute(color,3));const mat=new THREE.PointsMaterial({size:.055,map:new THREE.CanvasTexture(canvas),transparent:true,opacity:.85,vertexColors:true,depthWrite:false,blending:THREE.AdditiveBlending});const points=new THREE.Points(geo,mat);points.frustumCulled=false;scene.add(points);let cursor=0,emitted=0;return {emit(origin,force=.3,impact=false){const amount=impact?28:10;emitted+=amount;for(let k=0;k<amount;k++){const i=cursor++%count,j=i*3,a=Math.random()*Math.PI*2,speed=(.3+Math.random()*.65)*(impact?2:1);pos[j]=origin.x;pos[j+1]=origin.y+.015;pos[j+2]=origin.z;velocity[j]=Math.cos(a)*speed;velocity[j+1]=.25+Math.random()*.45+force*.2;velocity[j+2]=Math.sin(a)*speed;life[i]=.35+Math.random()*.4;const warm=impact||k%3===0;color[j]=warm?1:.65;color[j+1]=warm?.78:.88;color[j+2]=warm?.4:1;}geo.attributes.color.needsUpdate=true;},update(dt){for(let i=0;i<count;i++){if(life[i]<=0)continue;life[i]-=dt;const j=i*3;if(life[i]<=0){pos[j+1]=1000;continue;}velocity[j+1]-=dt*1.7;for(let a=0;a<3;a++)pos[j+a]+=velocity[j+a]*dt;}geo.attributes.position.needsUpdate=true;},clear(){life.fill(0);pos.fill(1000);geo.attributes.position.needsUpdate=true;},get active(){return life.reduce((n,t)=>n+(t>0?1:0),0);},get emitted(){return emitted;}};}
